CREATE OR REPLACE FUNCTION public.post_reaction_counts(p_post uuid)
 RETURNS TABLE(emoji text, total integer, reacted boolean)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select r.emoji,
         count(*)::integer,
         coalesce(bool_or(r.user_id = auth.uid()), false)
  from public.activity_reactions r
  where r.post_id = p_post
  group by r.emoji;
$function$;

comment on function public.post_reaction_counts(p_post uuid) is 'Reactions on one post per emoji, and whether the caller is among them (N56). Never who else reacted.';

grant execute on function public.post_reaction_counts(p_post uuid) to anon;
grant execute on function public.post_reaction_counts(p_post uuid) to authenticated;
grant execute on function public.post_reaction_counts(p_post uuid) to service_role;
